 [STAThread]static void Main(){Application.EnableVisualStyles();string pref=Path.Combine(Storage.DataDirectory,"settings.json");byte[] backup=File.Exists(pref)?File.ReadAllBytes(pref):null;try{using(MainForm f=new MainForm()){f.Opacity=0;f.Show();Application.DoEvents();((Timer)F(f,"timer")).Stop();f.Audio.Stop();f.SetLoopView(false);Storage.Apply(f.Engine,Demo.Create());AudioClip clip=f.Engine.Tracks[0].Clip;long frames=f.Engine.Frames;foreach(string theme in Theme.Names){f.Engine.System.UiTheme=theme;f.ApplyAppearance();A(f.BackColor==Theme.Background&&f.ForeColor==Theme.Text,"theme applies "+theme);A(ReferenceEquals(clip,f.Engine.Tracks[0].Clip)&&frames==f.Engine.Frames,"appearance preserves audio and transport");}f.Engine.System.UiAccent="#AD64E8";f.ApplyAppearance();A(Theme.Accent==ColorTranslator.FromHtml("#AD64E8"),"custom accent applies");SystemConfig copy=Storage.Clone(f.Engine.System);A(copy.UiTheme==f.Engine.System.UiTheme&&copy.UiAccent=="#AD64E8","appearance settings serialize");f.Engine.System.ReduceMotion=true;f.ApplyAppearance();A(!Theme.Animate,"reduced motion applies");foreach(Size size in new Size[]{new Size(1100,780),new Size(1280,880),new Size(1600,1000)}){f.ClientSize=size;Application.DoEvents();TrackStrip[] strips=(TrackStrip[])F(f,"strips");foreach(TrackStrip strip in strips){Rectangle ring=(Rectangle)F(strip,"ring");A(ring.Top>135&&ring.Bottom<strip.Height-45,"ring fits "+size.Width);using(Bitmap b=new Bitmap(strip.Width,strip.Height))strip.DrawToBitmap(b,strip.ClientRectangle);}}SceneView scene=(SceneView)F(f,"scene");f.SetLoopView(true);f.ShowMainPage(0);Application.DoEvents();using(Bitmap b=new Bitmap(scene.Width,scene.Height))scene.DrawToBitmap(b,scene.ClientRectangle);Rectangle[] pads=(Rectangle[])F(scene,"pads");A(pads.Length==5&&pads[4].Right<scene.Width,"scene renders five usable pads");f.Engine.Clear(0);f.Engine.FreshInputBoundary=null;f.Engine.Config.Quantize=false;f.Engine.Tracks[0].Config.StartMode=0;typeof(SceneView).GetMethod("OnMouseDown",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(scene,new object[]{new MouseEventArgs(MouseButtons.Left,1,pads[0].X+20,pads[0].Y+20,0)});A(f.Engine.Tracks[0].State==PlayState.Recording,"scene ring starts real recording");f.Engine.Clear(0);A(Theme.NamedColor("Rosa").R==255&&Theme.NamedColor("Coral").G==111,"reference palette is available");f.Engine.Dirty=false;f.Close();}Console.WriteLine("TOTAL "+n+" theme checks passed");}catch(Exception e){Console.WriteLine("FAIL "+e);Environment.ExitCode=1;}finally{if(backup!=null)File.WriteAllBytes(pref,backup);else if(File.Exists(pref))File.Delete(pref);}}
